class CountModel:
    def __init__(self):
        self.counts = {}

    def fit(self, labels):
        for y in labels:
            self.counts[y] = self.counts.get(y, 0) + 1
        return self

    def predict(self):
        return max(self.counts, key=self.counts.get)

m = CountModel()
m.fit(["a", "a", "b"])
print(m.fit(["b", "c"]).predict(), len(m.counts))
```

(`max(d, key=d.get)` returns the key with the largest value; among equal values, the first one inserted.)

