class Base:
    def __init__(self, scale):
        self.scale = scale

    def f(self, x):
        return self.scale * x

class Child(Base):
    def __init__(self, scale, shift):
        super().__init__(scale)
        self.shift = shift

    def f(self, x):
        return super().f(x) + self.shift

c = Child(3, 4)
print(c.f(10) * 10 + isinstance(c, Base))
