class Module:
    def __init__(self):
        self.calls = 0

    def __call__(self, x):
        self.calls += 1
        return self.forward(x)

class Double(Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return 2 * x

class Twice(Module):
    def __init__(self, inner):
        super().__init__()
        self.inner = inner

    def forward(self, x):
        return self.inner(self.inner.forward(x))

d = Double()
t = Twice(d)
print(t(3), t.calls, d.calls)
```

