class Module:
    def __init__(self):
        self.children = []

    def add(self, m):
        self.children.append(m)
        return m

    def count(self):
        return 1 + sum(c.count() for c in self.children)

class Block(Module):
    def __init__(self, depth):
        super().__init__()
        if depth > 0:
            self.add(Block(depth - 1))
            self.add(Block(depth - 1))

print(Block(3).count())
```

