class A:
    def __init__(self):
        self.trace = [1]

    def f(self, x):
        return x + 1

class B(A):
    def __init__(self):
        self.trace = [2]
        super().__init__()
        self.trace.append(3)

    def f(self, x):
        return super().f(x * 2)

class C(B):
    def __init__(self):
        super().__init__()
        self.trace.append(4)

    def f(self, x):
        return 10 * super().f(x)

c = C()
print(100 * sum(c.trace) + c.f(3))
