class Base:
    def __init__(self):
        self.order = []

    def setup(self):
        self.order.append("Base")

class Left(Base):
    def setup(self):
        self.order.append("L")
        super().setup()

class Right(Base):
    def setup(self):
        self.order.append("R")
        super().setup()

class Both(Left, Right):
    def setup(self):
        self.order.append("B")
        super().setup()

b = Both()
b.setup()
print(b.order)
```

